# Deadbird - level 1: the Extraction Plant.
#
# A hub level: the Extraction Atrium in the middle, three keycard wings around it, the reactor at
# the end. Cyan (processing floor, down the west stairs) opens the containment wing; amber (in the
# research lab above it) opens the vault and turbine wing; crimson (on the turbine catwalk) opens
# the shortcut back into the atrium and the core hall to the reactor.
#
# Metres; x east, z north; heights go up from the atrium floor. See tools/make_map.py for the format.
# The whole map has to fit inside +-31.25 m.

room dock Loading Dock
room checkpoint Security Checkpoint
room atrium Extraction Atrium
room processing Processing Floor
room containment Containment Block
room ramp Lab Ramp
room lab Research Lab
room vault Server Vault
room gallery Pipe Gallery
room turbine Turbine Hall
room corehall Core Hall
room reactor Reactor Core

# ================================================================== LOADING DOCK (start)
sector dock room dock floor 0 ceil 7
    pts -4,-30  4,-30  4,-25  4,-24.5  4,-24  4,-23.5  4,-23  4,-22.5  8,-22.5  8,-18  2,-18  -2,-18  -8,-18  -8,-20  -8,-22  -8,-26  -4,-26
    ftex FLOOR_DOCK
    frule FLOOR_HAZARD 1,99 0,-10
    ctex CEILING_PANEL
    crule CEILING_LIGHT 3,3 1,1
    walls BASE_PLAIN BASE_PIPES BASE_PLAIN BASE_HAZARD / DOCK_PLATE DOCK_NUMBER DOCK_PLATE MID_POSTER_DANGER DOCK_PLATE MID_ARROW / TOP_CIRCUIT / top TOP_BEAM
    lows PLATE_SIDE
    ups TOP_BEAM

# the freight lift that lowers her in from the shaft above the dock ceiling
