    pts 4,-30  8,-30  8,-25  4,-25
    ftex FLOOR_GRATE
    walls BASE_HAZARD / DOCK_PLATE DOCK_NUMBER / TOP_CIRCUIT / top TOP_BEAM
    lows PLATE_SIDE
stairs dock_steps room dock 4,-25 8,-22.5 n 1 0 ceil 7 steps 5
    ftex STAIR_TREAD
    walls BASE_HAZARD / DOCK_PLATE / TOP_CIRCUIT / top TOP_BEAM
    lows PLATE_SIDE

# secret: a scratched panel in the west wall slides up into a closet
